for (const [name, source] of [
  ["data.js", data],
  ["builder/builder.tsx", builder],
  ["app.tsx", app],
]) {
  assert(!/\bmock\b/i.test(source), `${name} must not carry local mock data paths`);
}

assert.match(data, /window\.META_BOOT\s*=/, "boot file should expose static layout metadata only");
// S23 shell modernization pins: app.tsx is a real module bundled by esbuild
// into the single flow-editor.js artifact; the controller facade is
// constructed once at module scope with a deliberate window back-compat
// assignment, and data.js still executes ahead of the module body.
assert.match(app, /import \{ createMetaFlowController \} from "@flow-editor-core";/, "app shell must build the controller facade from @flow-editor-core");
assert.match(app, /\} from "@flow-editor-components";/, "app shell must import its views from @flow-editor-components");
assert.match(app, /import "\.\/data\.js";/, "app shell must import data.js so window.META_BOOT is assigned before the module body runs");
assert.match(app, /const MetaFlowController: any = createMetaFlowController\(\{ includeTestExports: false \}\);\s*window\.MetaFlowController = MetaFlowController;/, "app shell must keep the window.MetaFlowController back-compat assignment for browser smokes, live verification scripts, component views, and embedders");
assert.match(buildScript, /entryPoints: \[appEntry\],[\s\S]*?bundle: true,[\s\S]*?format: "iife",[\s\S]*?platform: "browser"/, "flow-editor.js must be a single esbuild iife bundle of the app.tsx shell entry");
assert(!/\b(MEMBERS|INSTANCES|TOOL_CATALOG|AGENT_DEFINITIONS|SKILL_REALMS|MODELS|SCHEMAS|DEPLOY_DEFAULTS|CONTRACT_META)\b/.test(data), "boot data file must not define live Meta catalogs");
assert(!/TEMPLATE_META|template:\s*TEMPLATE_META|untitled-mob|mob\.toml/.test(data), "boot data file must not define local template summary metadata");
assert.match(app, /MetaFlowController\.flowCatalogBootstrapState\(catalogPayload,/, "flow registry must hydrate saved Meta rows and sample templates through the controller bootstrap projection");
assert(!/STARTER_FLOWS/.test(app), "flow registry must not keep local seed-flow state");
assert.equal(packageJson.scripts?.["test:visual-contract"], "node test/handoff-visual-contract.test.cjs", "package scripts must expose the handoff visual fidelity contract directly");
assert.equal(packageJson.scripts?.["test:browser-interactions"], "node test/browser-interactions-smoke.cjs", "package scripts must expose rendered Graph and Agent interaction coverage");
assert.match(makefile, /test-flow-editor:[\s\S]*meta_flow_editor[\s\S]*test:browser-source[\s\S]*test:browser-interactions/, "make test-flow-editor must build the embedded host and run rendered browser coverage");
assert.match(ciWorkflow, /test:browser-source --silent[\s\S]*test:browser-interactions --silent/, "Flow Editor CI must run both source and interaction browser smokes");
assert.match(browserInteractionsSmoke, /\.port-out[\s\S]*document\.querySelectorAll\("\.edge"\)[\s\S]*reachable\.has\(to\)/, "browser interaction smoke must cover rendered graph port-to-edge creation");
