assert.match(browserSourceSmoke, /meta\/mob\.toml[\s\S]*image_generation[\s\S]*mob\.browser\.source[\s\S]*Use this skill to prove edited agent source rendering\./, "browser source smoke must prove edited real tool and inline skill data reaches rendered Meta mob.toml source");

