// A stale (mid-run edit) NON-execute deploy bails before writing any state.
// An execute:true deploy is an authoritative host side effect that already
// ran, so its outcome is persisted and the `deployed` host event fires even
// when the authoring revision moved on; only the local validation-sheet
// mutations stay gated behind the revision-currency check.
assert.match(app, /const handleDeploy = async \(\{ execute \}\) => \{[\s\S]*const projected = await buildMetaProjectedDocument\(\);[\s\S]*const document = projected\.document;[\s\S]*requestToken = projected\.requestToken;[\s\S]*MetaFlowController\.deployDocument\(document, \{ execute,\s*\.\.\.currentDraftGuard\(\) \}\);[\s\S]*const revisionCurrent = authoringRevisionIsCurrent\(requestToken\);[\s\S]*if \(!revisionCurrent && !execute\) return;[\s\S]*persistCurrentOutcome\(outcome\);[\s\S]*if \(execute\) emitHostEvent\("deployed",[\s\S]*if \(!revisionCurrent\) return;[\s\S]*setValidationResults\(outcome\.validationRows\)/, "execute deploys must persist outcome and fire the deployed host event even after a mid-run edit; only stale non-execute deploys and stale local validation-sheet writes bail");
// The outcome projection must read the freshest rows (flowsRef), never the
