assert(!/function\s+makeStep|case\s+["']parallel["'][\s\S]{0,180}dispatch:\s*["']fan_out["']|case\s+["']member["'][\s\S]{0,120}dependsMode:\s*["']all["']/.test(builder), "Basic editor must not keep a local semantic step factory");
assert.match(controller, /function contractDefaultValue/, "controller plane must read absent semantic defaults from the Meta contract");
assert(!/\|\|\s*["'](fan_out|all|Fresh|==|string|json|full_history|branch|next|success|carry|turn_driven)["']|kind:\s*["']Fresh["']/.test(builder + "\n" + inspector + "\n" + agents + "\n" + app), "UI plane must not hard-code Meta edit-control defaults");
assert.doesNotMatch(builderMemberStepControlBlock + "\n" + inspectorInstanceBlock, /MetaFlowController\.launchMode(?:Kind|Session|ForkSource|ForkContext)Patch/, "Basic and Graph launch controls must not compute launch patches locally");
assert(!/meta\/starters|source:\s*['"]starter['"]/.test(app + "\n" + builder + "\n" + agents + "\n" + graph + "\n" + inspector + "\n" + controller), "Flow Editor frontend must not refer to the removed starter skill realm");
assert(!/meta_gateway mobpack deploy|profile_templates/.test(controllerProjectionTest), "projection fixtures must not preserve legacy gateway deploy or profile-template compatibility contracts");
assert(!/DiffOnly|ArtifactOnly/.test(app + "\n" + builder + "\n" + graph + "\n" + inspector + "\n" + controller), "Fork context options must come from Meta ForkContext, not stale prototype labels");
assert(!/\bTopology\b|topology view/.test(app + "\n" + builder + "\n" + graph + "\n" + inspector + "\n" + agents + "\n" + controller + "\n" + mobpackRust + "\n" + controllerProjectionTest), "Flow Editor UI and schema copy must use Basic/Graph/Agent surface names, not legacy Topology naming");
assert.match(controller, /function configure/, "controller RPC endpoint must be configured with data, not discovered through the DOM");
assert.match(app, /function downloadExportResult/, "browser download behavior belongs to the app UI shell");
assert.match(controller, /function exportDownloadPayload[\s\S]*meta\/mobpacks\/export did not return content_base64[\s\S]*meta\/mobpacks\/export did not return media_type[\s\S]*meta\/mobpacks\/export did not return filename/, "browser download must fail closed through controller-owned Meta export metadata validation");
assert(!/result\.media_type\s*\|\|\s*["']application\/vnd\.meerkat\.mobpack["']|result\.filename\s*\|\|\s*["']meta-flow\.mobpack["']/.test(app), "browser download must not invent Meta export media type or filename");
assert.match(app, /function importParamsFromFile/, "browser file decoding belongs to the app UI shell");
assert.match(app, /function rpcUrlFromShell/, "browser RPC URL discovery belongs to the app UI shell");

// EchoText resyncs the local draft to the server-authoritative `value` on
// blur, not only inside the `[value]`-dep effect. A per-keystroke
// apply_operation that fails leaves the document value unchanged, so the
// effect never fires; without the blur resync the typed character stays in
// the field forever (phantom text not in the deployable document).
assert.match(
  echoText,
  /onBlur:\s*\(e\)\s*=>\s*\{[\s\S]*focusedRef\.current\s*=\s*false;[\s\S]*setDraft\(value\s*\?\?\s*""\);[\s\S]*\},/,
  "EchoText must resync the draft to the server-authoritative value on blur so a failed per-keystroke op cannot strand phantom text",
);

// Agent edits must not snapshot client studio history before a
// server-authoritative authoring op: snap() bumps authoringRevision (via
// markDraft) and the runner then drops any in-flight op whose enqueued
// revision is stale, silently discarding the prior agent edit. Undo/redo are
// server-backed (handleHistoryStep), so the studio history snap is dead here.
assert(
  !/studio\.snap\(\)/.test(agents),
  "Agent intent handlers must not call studio.snap() before a server-authoritative op (it self-cancels in-flight agent edits)",
);

assert.match(
  devServer,
  /requires META_FLOW_EDITOR_RPC_URL=<real \/flow-editor\/rpc endpoint>/,
  "dev server must require a real Meta RPC endpoint",
);
assert(!/sample_mobpacks/.test(devServer), "dev server must not serve sample mobpacks itself");
